<?php
declare(strict_types=1);

require_once __DIR__ . '/../_bootstrap.php';
iniciarSesionWeb();
if (empty($_SESSION['usuario_id']) || ($_SESSION['tipo_cuenta'] ?? '') !== 'ADMIN') { header('Location: ' . rutaBasePublica() . '/index.php'); exit; }
$mesAnterior = (new DateTimeImmutable('first day of this month', new DateTimeZone('America/La_Paz')))->modify('-1 month')->format('Y-m');
?>
<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reporte de planilla | Restaurante Rumbo al Cielo</title><link rel="stylesheet" href="<?= escaparHtml(rutaBasePublica()) ?>/assets/css/app.css"></head>
<body class="pagina-panel"><main class="panel"><header class="panel-cabecera"><a class="marca marca-enlace" href="<?= escaparHtml(rutaBasePublica()) ?>/admin/dashboard.php"><img src="<?= escaparHtml(rutaBasePublica()) ?>/assets/img/uab-favicon.png" alt=""><span><strong>Rumbo al Cielo</strong><small>ADMINISTRACIÓN</small></span></a><a class="boton-secundario" href="<?= escaparHtml(rutaBasePublica()) ?>/admin/dashboard.php">Volver al inicio</a></header>
<section class="panel-contenido panel-contenido-ancho"><span class="etiqueta etiqueta-verde">CIERRE MENSUAL</span><h1>Reporte de planilla</h1><p>El cálculo considera almuerzos entregados e inasistencias cobrables. Las afiliaciones mensuales aplican el mínimo configurado y las afiliaciones de familiares cargan el descuento al titular.</p>
<form class="formulario-empleado" id="formulario-reporte"><div class="campo-formulario"><label for="periodo">Mes cerrado</label><input id="periodo" name="periodo" type="month" max="<?= escaparHtml($mesAnterior) ?>" value="<?= escaparHtml($mesAnterior) ?>" required></div><button class="boton-formulario" type="submit">Generar reporte</button><button class="boton-secundario" type="button" id="consultar-reporte">Consultar guardado</button><button class="boton-secundario" type="button" id="exportar-csv">Descargar CSV</button></form>
<p class="mensaje" id="mensaje-reporte" role="status" aria-live="polite"></p><div id="tabla-reporte" class="lista-reservas"></div></section></main>
<script>
const form=document.querySelector('#formulario-reporte');const periodo=document.querySelector('#periodo');const aviso=document.querySelector('#mensaje-reporte');const zona=document.querySelector('#tabla-reporte');let filas=[];
function mostrar(datos){filas=datos; if(!datos.length){zona.textContent='No hay datos para el periodo seleccionado.';return;} const tabla=document.createElement('table');tabla.className='tabla-reservas';const thead=document.createElement('thead');const hr=document.createElement('tr');for(const titulo of ['Código','Empleado','Almuerzos titular','Monto titular','Almuerzos familiares','Penalización familiares','Total a descontar']){const th=document.createElement('th');th.textContent=titulo;hr.append(th);}thead.append(hr);const tbody=document.createElement('tbody');for(const fila of datos){const tr=document.createElement('tr');for(const valor of [fila.codigo_empleado,fila.nombre_empleado,fila.almuerzos_titular,`Bs ${Number(fila.monto_titular).toFixed(2)}`,fila.almuerzos_familiares,`Bs ${Number(fila.penalizacion_familiares).toFixed(2)}`,`Bs ${Number(fila.total_descuento).toFixed(2)}`]){const td=document.createElement('td');td.textContent=valor;tr.append(td);}tbody.append(tr);}tabla.append(thead,tbody);zona.replaceChildren(tabla);}
async function consultar(){const res=await fetch(`../api/reportes.php?periodo=${encodeURIComponent(periodo.value)}`);const data=await res.json();if(!data.exito)throw new Error(data.mensaje);mostrar(data.filas);}
form.addEventListener('submit',async(e)=>{e.preventDefault();const [anio,mes]=periodo.value.split('-').map(Number);const body=new FormData();body.set('accion','generar');body.set('anio',anio);body.set('mes',mes);try{const res=await fetch('../api/reportes.php',{method:'POST',body});const data=await res.json();if(!data.exito)throw new Error(data.mensaje);mostrar(data.filas);aviso.textContent=`Reporte generado para ${data.total_empleados} empleado(s).`;aviso.className='mensaje mensaje-exito';}catch(error){aviso.textContent=error.message;aviso.className='mensaje mensaje-error';}});
document.querySelector('#consultar-reporte').addEventListener('click',()=>consultar().catch(e=>{aviso.textContent=e.message;aviso.className='mensaje mensaje-error';}));
document.querySelector('#exportar-csv').addEventListener('click',()=>{if(!filas.length)return;const encabezado=['codigo_empleado','nombre_empleado','almuerzos_titular','monto_titular','almuerzos_familiares','penalizacion_familiares','total_descuento'];const contenido=[encabezado.join(','),...filas.map(f=>encabezado.map(k=>`"${String(f[k]??'').replaceAll('"','""')}"`).join(','))].join('\r\n');const enlace=document.createElement('a');enlace.href=URL.createObjectURL(new Blob(['\ufeff',contenido],{type:'text/csv;charset=utf-8'}));enlace.download=`planilla-${periodo.value}.csv`;enlace.click();URL.revokeObjectURL(enlace.href);});
</script></body></html>
